(function($, elementor) {
    $(window).on('elementor/frontend/init', function() {
        let moduleHandler = elementorModules.frontend.handlers.Base;
        let VLP_Ad_Banner;

        VLP_Ad_Banner = moduleHandler.extend({
            getDefaultSettings() {
                return {
                    selectors: {
                        main: '.vlp-ad-banner-wrap'
                    }
                }
            },
            getDefaultElements() {
                const {
                    main
                } = this.getSettings('selectors');

                return {
                    $main: this.$element.find(main)
                }
            },
            bindEvents: function() {
                this._execute();
            },
            _execute() {
                let $this = this,
                    $id = $this.getID(),
                    $main = $this.elements.$main;

                let $close = $('.vlp-banner-close', $main);

                if (!$close.length) {
                    return;
                }

                if ($this._getCookie('vlp-ad-banner-disabled') === '1') {
                    $main.hide();
                }

                $close.on("click", function() {
                    $main.fadeOut();
                    $this._setCookie('vlp-ad-banner-disabled', '1', 1 / 24);
                });
            },
            _setCookie($name, $value, $days, $secureFlag = true, $sameSiteFlag = 'None') {
                var $expires = "";
                var $days = $days ? $days : 7;

                if ($days) {
                    var date = new Date();
                    date.setTime(date.getTime() + ($days * 24 * 60 * 60 * 1000));
                    $expires = "; expires=" + date.toUTCString();
                }

                // Add Secure attribute if the secureFlag is true
                var $secureAttribute = $secureFlag ? '; Secure' : '';

                // Add SameSite attribute
                var $sameSiteAttribute = `; SameSite=${$sameSiteFlag}`;

                document.cookie = $name + "=" + $value + $expires + "; path=/" + $secureAttribute + $sameSiteAttribute;
            },

            _getCookie($name) {
                var nameEQ = $name + "=";
                var cookies = document.cookie.split(';');

                for (var i = 0; i < cookies.length; i++) {
                    var cookie = cookies[i];
                    while (cookie.charAt(0) == ' ') {
                        cookie = cookie.substring(1, cookie.length);
                    }
                    if (cookie.indexOf(nameEQ) == 0) {
                        return cookie.substring(nameEQ.length, cookie.length);
                    }
                }
                return null;
            },
        });

        elementorFrontend.elementsHandler.attachHandler('vlp-ad-banner', VLP_Ad_Banner);
    });
})(jQuery, window.elementorFrontend);